29	/** Authoring flow currently in flight, waiting for the composer's Save. */
30	export type PendingAuthoring =
31	  | { kind: "comment"; applied: AppliedAnnotation }
32	  | { kind: "insertion"; applied: AppliedAnnotation }
33	  | { kind: "replacement"; applied: AppliedAnnotation };
