35	/** Save the composer payload into the comment maps. */
36	export const saveCommentBody = (
37	  setters: PruneSetters,
38	  id: string,
39	  anchorText: string,
40	  payload: AnnotationComposerPayload
41	): void => {
42	  setters.setBodies((prev) => new Map(prev).set(id, payload.body));
43	  if (payload.images.length > 0) {
44	    setters.setImages((prev) => new Map(prev).set(id, payload.images));
45	  }
46	  setters.setCommentOriginalTexts((prev) => new Map(prev).set(id, anchorText));
47	};
