77	/** Toolbar button click handlers wired to {@link applyAnnotation}. */
78	export interface ToolbarHandlers {
79	  onCommentClick: () => void;
80	  onInsertClick: () => void;
81	  onReplaceClick: () => void;
82	  onDeleteClick: () => void;
83	  /** Dispatch the matching handler by kind; used by host-side hotkeys. */
84	  triggerAnnotation: (kind: AnnotationHandleKind) => void;
85	}
86	
87	/** Dependencies passed into the toolbar-handlers hook. */
88	export interface ToolbarHandlerDeps {
89	  editor: PlateEditor;
90	  maps: AnnotationMaps;
91	  setters: PruneSetters;
92	  setPending: Dispatch<SetStateAction<PendingAuthoring | null>>;
93	  onChange?: (snapshot: EditorSnapshot) => void;
94	}
