165	/**
166	 * Set `id`'s images when non-empty, drop the key when empty so the map keeps its
167	 * "absent key ⇒ no images" shape (the add path never stores empty arrays). Returns
168	 * the same map reference when nothing changes.
169	 */
170	const withImages = (
171	  map: Map<string, string[]>,
172	  id: string,
173	  images: string[]
174	): Map<string, string[]> => {
175	  if (images.length > 0) return new Map(map).set(id, images);
176	  if (!map.has(id)) return map;
177	  const next = new Map(map);
178	  next.delete(id);
179	  return next;
180	};
181	
182	/** The body + image maps + their setters for one body-bearing kind. */
183	interface UpdateTarget {
184	  body: Map<string, string>;
185	  images: Map<string, string[]>;
186	  setBody: PruneSetters["setBodies"];
187	  setImages: PruneSetters["setImages"];
188	}
189	
190	const updateTarget = (
191	  kind: "comment" | "insertion" | "replacement",
192	  current: AnnotationMaps,
193	  setters: PruneSetters
194	): UpdateTarget => {
195	  if (kind === "comment") {
196	    return {
197	      body: current.bodies,
198	      images: current.images,
199	      setBody: setters.setBodies,
200	      setImages: setters.setImages,
201	    };
202	  }
203	  if (kind === "insertion") {
204	    return {
205	      body: current.insertionNewTexts,
206	      images: current.insertionImages,
207	      setBody: setters.setInsertionNewTexts,
208	      setImages: setters.setInsertionImages,
209	    };
210	  }
211	  return {
212	    body: current.replacementTexts,
213	    images: current.replacementImages,
214	    setBody: setters.setReplacementTexts,
215	    setImages: setters.setReplacementImages,
216	  };
217	};
218	
219	/**
220	 * Replace the body + images of an existing body-bearing annotation in place.
221	 *
222	 * Mirrors {@link pruneRemovedAnnotation}'s shape (reads `current` so existence is
223	 * checked atomically) but writes instead of deletes. Only the text + image maps
224	 * for `id` change; `*OriginalTexts` and the Plate mark are left alone so the
225	 * anchor + drift baseline survive the edit. No-op when `id` is unknown, which
226	 * stops a stale edit from resurrecting a removed annotation. Persistence flows
227	 * through the host's existing maps-change effect — unlike removal there is no
228	 * Plate-value mutation to capture, so no explicit `onChange` is needed here.
229	 */
230	export const updateAnnotationMaps = (
231	  kind: "comment" | "insertion" | "replacement",
232	  id: string,
233	  body: string,
234	  images: string[],
235	  current: AnnotationMaps,
236	  setters: PruneSetters
237	): void => {
238	  const target = updateTarget(kind, current, setters);
239	  if (!target.body.has(id)) return;
240	  target.setBody(new Map(target.body).set(id, body));
241	  target.setImages(withImages(target.images, id, images));
242	};
