244	/**
245	 * Memoized `removeAnnotation` handle method: clears the Plate mark, prunes every
246	 * map for the id, and pushes a fresh snapshot. Extracted (like {@link useReadyHandle})
247	 * so `ReviewEditor` stays under the per-function line cap.
248	 */
249	export const useRemoveAnnotation = (
250	  editor: PlateEditor,
251	  maps: AnnotationMaps,
252	  setters: PruneSetters,
253	  onChange?: (snapshot: EditorSnapshot) => void
254	): ReviewEditorHandle["removeAnnotation"] =>
255	  useCallback(
256	    (kind, id) => {
257	      if (kind === "task") {
258	        removeTaskToggle(editor, id);
259	        onChange?.(snapshotOf(editor, maps));
260	        return;
261	      }
262	      removeAnnotationMark(editor, kind, id);
263	      const next = pruneRemovedAnnotation(kind, id, maps, setters);
264	      onChange?.(snapshotOf(editor, next));
265	    },
266	    [editor, maps, onChange, setters]
267	  );
268	
269	/**
270	 * Memoized task-checkbox toggle handler for {@link TaskToggleContext}. Applies
271	 * the toggle to the editor value (see `applyTaskToggle`) and re-emits the
272	 * snapshot so the host persists the new `checked` + `task_<id>` marks.
273	 */
274	export const useTaskToggle = (
275	  editor: PlateEditor,
276	  maps: AnnotationMaps,
277	  onChange?: (snapshot: EditorSnapshot) => void
278	): ((element: unknown) => void) =>
279	  useCallback(
280	    (element) => {
281	      applyTaskToggle(editor, element);
282	      onChange?.(snapshotOf(editor, maps));
283	    },
284	    [editor, maps, onChange]
285	  );
