287	/**
288	 * Memoized `updateAnnotation` handle method bound to the current maps + setters.
289	 * Extracted (like {@link useReadyHandle}) so `ReviewEditor` stays under the
290	 * per-function line cap. Persistence flows through the host's maps-change effect.
291	 */
292	export const useUpdateAnnotation = (
293	  maps: AnnotationMaps,
294	  setters: PruneSetters
295	): ReviewEditorHandle["updateAnnotation"] =>
296	  useCallback(
297	    (kind, id, body, images) => updateAnnotationMaps(kind, id, body, images, maps, setters),
