301	/** Annotation handle kinds that route through the composer. */
302	export type ComposerKind = PendingAuthoring["kind"];
303	
304	/** Dispatch the composer payload to the matching map saver. */
305	export const dispatchComposerSave = (
306	  pending: PendingAuthoring,
307	  payload: AnnotationComposerPayload,
308	  setters: PruneSetters
309	): void => {
310	  const { id, anchorText } = pending.applied;
311	  if (pending.kind === "comment") {
312	    saveCommentBody(setters, id, anchorText, payload);
313	    return;
314	  }
315	  if (pending.kind === "insertion") {
316	    saveInsertionBody(setters, id, anchorText, payload);
317	    return;
318	  }
319	  saveReplacementBody(setters, id, anchorText, payload);
320	};
321	
322	/**
323	 * Roll back the eagerly-applied annotation mark when the composer is cancelled.
324	 * Pattern A applies the mark on open, so every cancel route (button, Escape,
325	 * overlay) must remove it or the selection stays highlighted with no body. No
326	 * map pruning is needed: a body is only stored on save, so the cancelled id
327	 * never entered the annotation maps. Mirrors {@link dispatchComposerSave}.
328	 */
329	export const dispatchComposerCancel = (
330	  pending: PendingAuthoring | null,
331	  editor: PlateEditor,
332	  maps: AnnotationMaps,
333	  onChange?: (snapshot: EditorSnapshot) => void
334	): void => {
335	  if (pending === null) return;
336	  removeAnnotationMark(editor, pending.kind, pending.applied.id);
337	  onChange?.(snapshotOf(editor, maps));
338	};
