17	 * selectors — see `docs/08-testing.md#playwright-bdd-selectors`).
18	 *
19	 * @example
20	 *   export const CommentLeaf = createAnnotationLeaf(
21	 *     "mark",
22	 *     "text-anno-comment bg-anno-comment/10 rounded-sm px-0.5",
23	 *     "CommentLeaf",
24	 *     "annotation-comment",
25	 *   );
26	 */
27	export const createAnnotationLeaf = (
28	  tag: ElementType,
