1	/**
2	 * Syntax-highlighting `decorate` for fenced code blocks. Replaces the old
3	 * Shiki-HTML-via-`dangerouslySetInnerHTML` renderer: instead of an opaque blob,
4	 * Shiki tokens are projected onto the real `code_line` leaves as ephemeral
5	 * `code_syntax` decoration ranges, so the code stays selectable and annotatable
6	 * while still being coloured. Rendered by {@link ../components/CodeSyntaxLeaf.tsx}.
7	 *
8	 * Shiki's highlighter loads asynchronously (dynamic grammar/theme imports) but
9	 * Slate's `decorate` is synchronous. The bridge: tokens are cached per
10	 * `(lang, code)`; on a miss the decorate returns no ranges and kicks a one-time
11	 * async tokenize, then calls `editor.api.redecorate()` once the tokens land —
12	 * a single event-driven re-run, never a `useEffect` state-sync loop (CLAUDE.md
13	 * §7.4). Once the highlighter is warm, `codeToTokensWithThemes` is synchronous,
14	 * so subsequent edits colour without a flash.
15	 *
16	 * @see ./codeTokens.ts — the pure offset/colour math this wires into Slate.
17	 */
18	import {
19	  createSlatePlugin,
20	  type Descendant,
21	  type NodeEntry,
22	  type SlateEditor,
23	  type TElement,
24	  type TNode,
25	} from "platejs";
26	import type { ThemedTokenWithVariants } from "shiki/core";
27	
28	import { type CodeSyntaxRange, lineTokensToSegments, segmentsToLeafRanges } from "./codeTokens.ts";
29	import { highlightToThemedTokens } from "./shiki.ts";
30	
31	/** Cap the token cache: editing code mints a fresh `(lang, code)` key on every
32	 * keystroke, so an unbounded map would grow without limit over a long session. */
33	const maxCacheEntries = 256;
34	
35	const tokenCache = new Map<string, ThemedTokenWithVariants[][]>();
36	/** key → editors awaiting that key's in-flight tokenize, so every editor showing
37	 * the same code redecorates when tokens land (not just the one that kicked it). */
38	const pending = new Map<string, Set<SlateEditor>>();
39	
40	const cacheTokens = (key: string, tokens: ThemedTokenWithVariants[][]): void => {
41	  tokenCache.set(key, tokens);
42	  if (tokenCache.size > maxCacheEntries) {
43	    const oldest = tokenCache.keys().next().value;
44	    if (oldest !== undefined) tokenCache.delete(oldest);
45	  }
46	};
47	
48	const isCodeBlock = (node: TNode): node is TElement =>
49	  "type" in node && node.type === "code_block" && Array.isArray(node.children);
50	
51	const isCodeLine = (node: Descendant): node is TElement =>
52	  "children" in node && Array.isArray(node.children);
53	
54	const leafText = (leaf: Descendant): string =>
55	  "text" in leaf && typeof leaf.text === "string" ? leaf.text : "";
56	
57	const lineText = (line: TElement): string => line.children.map(leafText).join("");
58	
59	/** Join a code block's `code_line` children into the source Shiki tokenizes. */
60	const blockCode = (lines: TElement[]): string => lines.map(lineText).join("\n");
61	
62	const cacheKey = (lang: string, code: string): string => `${lang} ${code}`;
63	
64	const blockLang = (block: TElement): string =>
65	  "lang" in block && typeof block.lang === "string" ? block.lang : "text";
66	
67	/**
68	 * Tokenize `code` once and cache it, then re-run decoration so the freshly
69	 * tokenized block paints. A block decorated repeatedly before its tokens resolve
70	 * kicks only a single tokenize; editors that ask for the same in-flight key join
71	 * its wait list so they all redecorate together when the tokens land.
72	 */
73	const loadTokens = (editor: SlateEditor, key: string, code: string, lang: string): void => {
74	  const waiting = pending.get(key);
75	  if (waiting !== undefined) {
76	    waiting.add(editor);
77	    return;
78	  }
79	  const waiters = new Set<SlateEditor>([editor]);
80	  pending.set(key, waiters);
81	  highlightToThemedTokens(code, lang)
82	    .then((tokens) => {
83	      cacheTokens(key, tokens);
84	      pending.delete(key);
85	      for (const waiter of waiters) waiter.api.redecorate();
86	    })
87	    .catch(() => {
88	      pending.delete(key);
89	    });
90	};
91	
92	/**
93	 * Build the decoration ranges for one code block. Returns `[]` (and schedules a
94	 * tokenize) until the highlighter is warm, so an un-highlighted block renders as
95	 * plain selectable code rather than blocking.
96	 */
97	const decorateCodeBlock = (
98	  editor: SlateEditor,
99	  block: TElement,
100	  blockPath: number[]
101	): CodeSyntaxRange[] => {
102	  const lines = block.children.filter(isCodeLine);
103	  if (lines.length === 0) return [];
104	  const code = blockCode(lines);
105	  const lang = blockLang(block);
106	  const key = cacheKey(lang, code);
107	  const tokens = tokenCache.get(key);
108	  if (tokens === undefined) {
109	    loadTokens(editor, key, code, lang);
110	    return [];
111	  }
112	  const ranges: CodeSyntaxRange[] = [];
113	  for (const [lineIndex, line] of lines.entries()) {
